style.css:
/* Roblox-themed background for the whole page */
body {
  background-image: url('https://www.roblox.com/assets/roblox_logo.png'); /* Example Roblox logo background */
  background-repeat: no-repeat;
  background-position: center top;
  background-size: 300px auto;
  background-color: #e2231a; /* Roblox's signature red */
  color: white; /* Make text readable */
  font-family: 'Arial', sans-serif;
  min-height: 100vh;
  margin: 0;
  padding: 0;
}

/* Optional: Add a subtle dark overlay */
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.3);
  pointer-events: none;
  z-index: -1;
}
